72	    public Collection<Pet> findAllPets() throws DataAccessException {
73	        return petRepository.findAll();
74	    }
75	
76	    @Override
77	    @Transactional(readOnly = true)
78	    public Page<Pet> findPets(Pageable pageable) throws DataAccessException {
79	        return petRepository.findAll(pageable);
80	    }
81	
82	    @Override
83	    @Transactional
84	    public void deletePet(Pet pet) throws DataAccessException {
