98	    }
99	
100	    @Override
101	    @Transactional
102	    public void deleteVisit(Visit visit) throws DataAccessException {
103	        visitRepository.delete(visit);
104	    }
105	
106	    @Override
107	    @Transactional(readOnly = true)
108	    public Vet findVetById(int id) throws DataAccessException {
109	        return findEntityById(() -> vetRepository.findById(id));
110	    }
111	
112	    @Override
113	    @Transactional(readOnly = true)
114	    public Collection<Vet> findAllVets() throws DataAccessException {
115	        return vetRepository.findAll();
116	    }
117	
118	    @Override
119	    @Transactional
120	    public void saveVet(Vet vet) throws DataAccessException {
121	        vetRepository.save(vet);
122	    }
123	
124	    @Override
125	    @Transactional
126	    public void deleteVet(Vet vet) throws DataAccessException {
