128	    }
129	
130	    @Override
131	    @Transactional(readOnly = true)
132	    public Collection<Owner> findAllOwners() throws DataAccessException {
133	        return ownerRepository.findAll();
134	    }
135	
136	    @Override
137	    @Transactional(readOnly = true)
138	    public Page<Owner> findOwners(String lastName, Pageable pageable) throws DataAccessException {
139	        if (lastName != null) {
140	            return ownerRepository.findByLastName(lastName, pageable);
141	        }
142	        return ownerRepository.findAll(pageable);
143	    }
144	
145	    @Override
146	    @Transactional
147	    public void deleteOwner(Owner owner) throws DataAccessException {
148	        ownerRepository.delete(owner);
149	    }
150	
151	    @Override
152	    @Transactional(readOnly = true)
153	    public PetType findPetTypeById(int petTypeId) {
154	        return findEntityById(() -> petTypeRepository.findById(petTypeId));
155	    }
156	
157	    @Override
158	    @Transactional(readOnly = true)
159	    public Collection<PetType> findAllPetTypes() throws DataAccessException {
160	        return petTypeRepository.findAll();
161	    }
162	
163	    @Override
164	    @Transactional
165	    public void savePetType(PetType petType) throws DataAccessException {
166	        petTypeRepository.save(petType);
167	    }
168	
169	    @Override
170	    @Transactional
171	    public void deletePetType(PetType petType) throws DataAccessException {
172	        petTypeRepository.delete(petType);
173	    }
174	
175	    @Override
176	    @Transactional(readOnly = true)
177	    public Specialty findSpecialtyById(int specialtyId) {
178	        return findEntityById(() -> specialtyRepository.findById(specialtyId));
179	    }
180	
181	    @Override
182	    @Transactional(readOnly = true)
183	    public Collection<Specialty> findAllSpecialties() throws DataAccessException {
184	        return specialtyRepository.findAll();
185	    }
186	
187	    @Override
188	    @Transactional
189	    public void saveSpecialty(Specialty specialty) throws DataAccessException {
190	        specialtyRepository.save(specialty);
191	    }
192	
193	    @Override
194	    @Transactional
195	    public void deleteSpecialty(Specialty specialty) throws DataAccessException {
196	        specialtyRepository.delete(specialty);
197	    }
198	
199	    @Override
200	    @Transactional(readOnly = true)
201	    public Collection<PetType> findPetTypes() throws DataAccessException {
202	        return petRepository.findPetTypes();
203	    }
204	
205	    @Override
206	    @Transactional(readOnly = true)
207	    public Owner findOwnerById(int id) throws DataAccessException {
208	        return findEntityById(() -> ownerRepository.findById(id));
209	    }
210	
211	    @Override
212	    @Transactional(readOnly = true)
213	    public Pet findPetById(int id) throws DataAccessException {
214	        return findEntityById(() -> petRepository.findById(id));
215	    }
216	
217	    @Override
218	    @Transactional
219	    public void savePet(Pet pet) throws DataAccessException {
220	        pet.setType(findPetTypeById(pet.getType().getId()));
221	        petRepository.save(pet);
222	    }
223	
224	    @Override
225	    @Transactional
226	    public void saveVisit(Visit visit) throws DataAccessException {
227	        visitRepository.save(visit);
228	
229	    }
230	
231	    @Override
232	    @Transactional(readOnly = true)
233	    public Collection<Vet> findVets() throws DataAccessException {
234	        return vetRepository.findAll();
235	    }
236	
237	    @Override
238	    @Transactional
239	    public void saveOwner(Owner owner) throws DataAccessException {
240	        if (owner.getCustomerCode() == null) {
241	            owner.setCustomerCode(generateCustomerCode(owner));
242	        }
243	        ownerRepository.save(owner);
244	
245	    }
246	
247	    /**
248	     * Builds an owner's customer code formatted {@code '<CITY3>-<LAST3>-<NNNN>'}, where CITY3 is the
249	     * upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
250	     * last name and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number
251	     * of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
252	     */
253	    private String generateCustomerCode(Owner owner) {
254	        String city = owner.getCity();
255	        int sequence = (int) ownerRepository.findAll().stream()
256	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
257	            .count() + 1;
258	        return String.format("%s-%s-%04d", prefix3(city), prefix3(owner.getLastName()), sequence);
259	    }
260	
261	    /** The upper-cased first three letters of {@code value} (fewer if it is shorter). */
262	    private static String prefix3(String value) {
263	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
264	    }
265	
266	    @Override
267	    @Transactional(readOnly = true)
268	    public boolean existsOwnerWithTelephone(String telephone) throws DataAccessException {
269	        return ownerRepository.existsByTelephone(telephone);
270	    }
271	
272	    @Override
273	    @Transactional(readOnly = true)
274	    public boolean existsOwnerWithEmail(String email) throws DataAccessException {
275	        if (email == null || email.isBlank()) {
276	            return false;
277	        }
278	        return ownerRepository.existsByEmailIgnoreCase(email);
279	    }
280	
281	    /**
282	     * Counts the existing owners whose firstName and lastName match the given values
283	     * case-insensitively. Used to record an owner's namesake count at creation time.
284	     */
285	    @Override
286	    @Transactional(readOnly = true)
287	    public int countOwnersByName(String firstName, String lastName) throws DataAccessException {
288	        if (firstName == null || lastName == null) {
289	            return 0;
290	        }
291	        return (int) ownerRepository.findAll().stream()
292	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
