338	    private List<Owner> findHouseholdMembers(String lastName, String address) {
339	        String normalizedLastName = normalizeHouseholdField(lastName);
340	        String normalizedAddress = normalizeHouseholdAddress(address);
341	        if (normalizedLastName == null || normalizedAddress == null) {
342	            return List.of();
343	        }
344	        return ownerRepository.findAll().stream()
345	            .filter(existing -> normalizedLastName.equals(normalizeHouseholdField(existing.getLastName()))
346	                && normalizedAddress.equals(normalizeHouseholdAddress(existing.getAddress())))
347	            .toList();
348	    }
349	
350	    /**
351	     * Normalizes a household-identity field for comparison by trimming, collapsing internal
352	     * runs of whitespace to a single space and lower-casing, so values that differ only in
353	     * whitespace or letter case are treated as equal.
354	     */
355	    private static String normalizeHouseholdField(String value) {
356	        if (value == null) {
357	            return null;
358	        }
359	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
360	    }
361	
362	    /**
363	     * Normalizes an address for household comparison and identity using the same canonical form
364	     * applied when an owner is created (trim/collapse whitespace, upper-case, expand common
365	     * abbreviations), so comparisons always use the normalized address regardless of the form in
366	     * which either value was originally supplied. Returns {@code null} when the address is absent
367	     * or blank, since no household can be formed without one.
368	     */
369	    private static String normalizeHouseholdAddress(String address) {
370	        String normalized = AddressNormalizer.normalize(address);
371	        if (normalized == null || normalized.isBlank()) {
